"""A Class with low level functionality for headless iCOM Fx connections, sending efs files,
reading iCOM Fx message tags and errors"""

import builtins
from ctypes import byref, c_ushort, c_short, windll, c_long, c_char_p
from ctypes.wintypes import DWORD
from collections import OrderedDict
from interops.libraries.icom.icom_tag_mappings import defn_to_tag_map
from interops.libraries.icom.icom_error_handling import IcomMessageError, IcomTagError, exception_from_err
from interops.libraries.icom.icom_error_codes import *  #TODO - not ideal, find alternative to import all errors codes?
import time
import logging

logger = logging.getLogger(__name__)


class IcomFx():
    '''
    Fx interaction.

    Create an instance of this class to begin interacting with the Fx server.
    NB: Requires a Vx connection to be running in same process.

    Uses Elekta iCOMClient.dll directly from Python.
    iCOMClient.dll is 32-bit and only runs on 32-bit Python.

    Example:

        vx.connect(hostip=ip, timeout_millis=timeout)
        fx.connect(hostip=ip, machine=linac, timeout_millis=timeout)
        time.sleep(5)
        fx.load_and_send(r"C:\python32bit\AglTest01_Static_Open_BAD.efs")
        confirm = vx.wait_until_state("CONFIRM SETTINGS", timeout=20, filepath=file_out)
        fx.send_confirm()
        ready = vx.wait_until_state("READY TO START", timeout=20)
    '''

    def __init__(self, lib_path):

        self.icom = windll.LoadLibrary(lib_path)

    def connect(self, hostip, machine, timeout_millis=10000):
        '''
        Open new connection to Fx server.

        Args:
        hostip(str) - IP Address of linac host
        machine(str) - Linac machine number
        timeout_millis(int) -  Timeout to get connection (milliseconds)

        Returns:
        boolean - True if successful

        Raises:
        IcomConnectionError if unsuccessful
        '''

        # In python 3, strings are unicode, but c_char_p() expects a byte object.
        # Convert the unicode string to a byte string before passing to c_char_p().
        ip_ptr = c_char_p(hostip.encode('utf-8'))
        timeout = c_long(timeout_millis)
        # For python 3, convert the machine_id to a C char * type, before passing
        # to iCOMFxConnect()(as per icom ref)
        machine_id_ptr = c_char_p(machine.encode('utf-8'))
        result = self.icom.iCOMFXConnect(ip_ptr, timeout, machine_id_ptr)

        if result > 0:
            self.icom_handle = result
            print("Connected to Fx with Handle: " + str(self.icom_handle))
            return True
        else:
            raise exception_from_err("FAILED TO CONNECT TO FX: ", result)

    def parse_efs(self, filename):
        '''
        Parse an efs file and return a dictionary of tags in the order declared within the given file.

        NB: Backing is an ordered dictionary, duplicate tags will be removed.

        Args:
        filename (str) - Path to the efs file

        Returns: An ordered dictionary of tags with the key in the format {padded_hex_tag - controlpoint}
        e.g. 50010101-1.  Values are tuples of (tag, value, controlpoint) with tag in integer format.
        e.g. (1342243388,20,1)
        '''
        logger.info("parse_efs - " + filename)
        tags = OrderedDict()
        with open(filename, 'r') as f:
            for line in f:
                line = line.strip()
                parts = line.split(' ')
                tag_cp = parts[0].split(',')
                taghi = tag_cp[0]
                taglo = tag_cp[1].split('-')[0].zfill(4)
                hex_int = int("0x" + taghi + taglo, 16)
                hex_tag = hex(hex_int)
                cp = int(tag_cp[1].split('-')[1])
                value = " ".join(parts[1:])
                key = taghi + taglo + "-" + str(cp)
                tags[key] = (hex_int, value, cp)

        return tags

    def disconnect(self):
        '''
        Close connection to iCOM Fx server.
        '''
        if hasattr(self, "icom_handle"):
            logger.info("disconnect success")
            return self.icom.iCOMDisconnect(self.icom_handle)

    def begin_message(self):
        '''
        Create a new Fx message ready to insert tags.

        Returns:
        Integer handle of new message.
        '''
        result = self.icom.iCOMBeginMessage(self.icom_handle)
        if result > 0:
            # Got a message handle
            logger.info("begin_message success")
            return result
        else:
            raise exception_from_err("Failed to begin FX message", result)

    def delete_message(self, msg_handle):
        '''
        Delete Fx message from iCOM.

        Args:

        msg_handle(int) - Handle of message to be deleted.
        '''
        result = self.icom.iCOMDeleteMessage(msg_handle)

    def insert_tag_value(self, msg_handle, tag, tag_val, ctrl_pt):
        '''
        Insert a tag value in Fx message.

        Args:
        msg_handle (int) - Handle to client Fx message
        tag(int) - Tag id
        tag_val(str) - Tag value
        ctrl_pt(int) - Control Point

        Returns:
        True if OK.

        Raises:
        IcomTagError if tag failed client side checks.
        '''
        # iCOMInsertTagVal() expects the tag value (3rd argument) to be a pointer to a null-terminated string.
        # For python 3, encode tag_val as unicode and use ctypes c_char_p() to represent this as a c char * type.
        tag_val_ptr = c_char_p(tag_val.encode('utf-8'))
        result = self.icom.iCOMInsertTagVal(msg_handle, tag, tag_val_ptr, c_ushort(ctrl_pt))
        if result == ICOM_RESULT_OK:
            return True
        else:
            raise exception_from_err("Failed to insert tag value", result)

    def send_message(self, msg_handle):
        '''
        Returns a new handle to a message created by FX.
        Blocks until sent.
        This handle must be deleted by client.
        '''
        logger.info("send_message")
        resp_msg = self.icom.iCOMSendMessage(msg_handle)
        if resp_msg < 1:
            raise exception_from_err("Failed to send message", resp_msg)
        self.delete_message(msg_handle)
        return resp_msg

    def send_confirm(self, retries=3):
        '''
        Send a confirm settings instruction to iCOM.
        Updated to preferred method of iCOMSendConfirmEx - NA
        Returns:
        True if OK.
        '''
        for n in range(retries):
            result = self.icom.iCOMSendConfirmEx(self.icom_handle, 1)
            if result == ICOM_RESULT_OK:
                logger.info("send_confirm success")
                return True
            else:
                logger.error(("Failed to send confirm after attempt " + str(n), "icom result " + result))
                time.sleep(10)
        raise exception_from_err("Failed to send confirm", result)
        return False

    def send_unconfirm(self):
        '''
        Send an unconfirm settings instruction to iCOM.

        Returns:
        True if OK.
        '''
        result = self.icom.iCOMSendConfirmEx(self.icom_handle, 0)
        if result == ICOM_RESULT_OK:
            return True
        else:
            raise exception_from_err("Failed to send unconfirm", result)

    def send_cancel(self):
        '''
        Send a cancel instruction to iCOM.

        Returns:
        True if OK.
        '''
        result = self.icom.iCOMSendCancel(self.icom_handle)
        if result == ICOM_RESULT_OK:
            return True
        else:
            raise exception_from_err("Failed to send_cancel", result)

    def get_error_code(self, msg_handle):
        '''
        Gets the error code from an iCom-Fx treatment settings acknowledgement message.

        NB: This should be called AFTER message has been sent successfully.

        Args:
        msg_handle(int) - Handle of message that has been returned by Fx server

        Returns:
        Tuple of error number and textual error value.
        '''
        error_codes = {0: 'OK',
                       1: 'NOT SUPPORTED',
                       2: 'UNDER SPECIFIED',
                       3: 'OVER SPECIFIED',
                       4: 'OUTSIDE RANGE',
                       5: 'INCONSISTENCY',
                       6: 'MISMATCH TEXT',
                       7: 'PROTOCOL ERROR',
                       8: 'NOT READY',
                       9: 'WRONG MACHINE',
                       10: 'CHECKSUM ERROR',
                       11: 'VERSION ERROR',
                       12: 'NOT LICENSED'}

        result = self.icom.iCOMGetErrorCode(msg_handle)
        result = c_short(result).value
        return (result, error_codes.get(result, 'UNKNOWN'))

    def get_error_tag(self, msg_handle):
        '''
        Gets the error tag from an iCom-Fx treatment settings acknowledgement message.

        NB: This should be called AFTER message has been sent successfully.

        Args:
        msg_handle(int) - Handle of message that has been returned by Fx server
        '''
        # these are the decimalised hex codes for the tags
        #tag_decode = {0 : '', 1879179270 : 'Leaf Width',1342242823:'Gantry Angle'}
        # Create a dictionary from the original tag map with hex converted back to decimal.
        # This allows for error tag to be showed in human readable form
        tag_decode = {builtins.int(v, 16): k for k, v in defn_to_tag_map.items()}
        tag = DWORD()
        result = self.icom.iCOMGetErrorTag(msg_handle, byref(tag))
        tag_value = int(tag.value)
        logger.error("icom error tag - " + str(tag_value))
        return (tag_value, tag_decode.get(tag_value, 'UNKNOWN'))

    def get_error_control_point(self, msg_handle):
        '''
        Get the control point error location from an iCom-Fx treatment settings acknowledgement message.
        NB: This should be called AFTER message has been sent successfully.

        Args:
        msg_handle(int) - Handle of message that has been returned by Fx server

        Returns:
        Integer value of failed Control point
        '''
        result = self.icom.iCOMGetErrorControlPoint(msg_handle)
        return result

    def connection_state_ok(self):
        '''
        Check health and availability of iCOM  Fx connection .

        Returns:
        True if The connection has started and is okay(state=1) else False
        '''

        state = self.icom.iCOMGetConnectionState(self.icom_handle)
        if state == ICOM_RESULT_OK:
            return True
        else:
            return False

    def connection_state(self):
        '''
        Get the connection state.

        Returns:
            state (str) - The current connection state as textual value.
        '''

        state = self.icom.iCOMGetConnectionState(self.icom_handle)
        return decode_dict.get(state, "UNKNOWN")

    def insert_tags(self, msg, tags):
        '''
        Insert tag values into Fx message.

        Args:
        msg (int) - Handle to client Fx message
        tags (dict) - Tags with values to insert

        Returns:
        List of errors for tags that were rejected
        '''
        tag_count = 0
        error_list = []
        for tag, values in tags.items():
            # No need to include this tag, icom does this for us
            if tag.startswith('70010001'):
                continue
            tag = values[0]
            tag_val = values[1]
            cp = values[2]
            try:
                self.insert_tag_value(msg, tag, tag_val, cp)
                tag_count += 1
            except IcomTagError as ipe:
                logger.info("Insert_tags tag rejected - " + ipe.desc)
                error_list.append(str(tag) + "-" + ipe.desc)

        return error_list

    def check_for_errors(self, msg_handle):
        '''
        Resolve error tag details from FX response mesage.
        This should be called AFTER send_message() to confirm message correctness.

        Args:
        msg_handle(int) - Handle of message that has been returned by Fx server

        Returns:
        True if message ok.

        Raises:
        IcomMessageError containing error details if prescription invalid.
        '''
        tag = self.get_error_tag(msg_handle)
        code, desc = self.get_error_code(msg_handle)
        cp = self.get_error_control_point(msg_handle)

        self.delete_message(msg_handle)

        if code != 0:
            raise IcomMessageError("Invalid Fx message sent", code, (code, desc, cp))

        return True

    def load_and_create(self, efs_file):
        '''
        Parse efs file and insert tags into message.

        Args:
        efs_file (str) - Path to the efs file to load

        Returns:
        tuple of msg handle (int), tags(dict), errors(list)
        '''
        tags = self.parse_efs(efs_file)
        fx_msg = self.begin_message()
        errors = self.insert_tags(fx_msg, tags)
        return (fx_msg, tags, errors)

    def load_and_send(self, efs_file):
        '''
        Parse efs file and insert tags into message.

        Args:
        efs_file (str) - Path to the efs file to load

        Returns:
        True if OK.

        Raises:
        IcomMessageError if errors found before send this will contain the errors in the description
        field of the exception.
        IcomMessageError if error found after send the error details will be in the description field.

        '''
        tags = self.parse_efs(efs_file)
        fx_msg = self.begin_message()
        errors = self.insert_tags(fx_msg, tags)
        if not errors:
            # No errors found while creating message
            if self.connection_state_ok():
                time.sleep(1)
                resp_msg = self.send_message(fx_msg)
                # Check that Fx server has validated message as OK
                # Raises IcomMessageError if problem with prescription during send to Fx.
                self.check_for_errors(resp_msg)
        else:
            raise IcomMessageError("Invalid tags found during Fx message creation", errors[0][0], errors)

        return True
